update public.schede set alert = array['Rischi (testo in inglese): The wood, sawdust and resins from various species of pine can cause dermatitis in sensitive people.']::text[] where id = '6794519e-fc55-4117-b0b5-52aa7e7b7ef9' and alert = array['Rischi: il legno, la segatura e le resine di varie specie di pino possono causare dermatite nelle persone sensibili.']::text[];
